package local.finalclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;
import net.minecraft.client.*;import net.minecraft.resources.Identifier;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.effect.*;import net.minecraft.world.item.*;import net.minecraft.world.level.GameType;import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.spell_engine.api.spell.*;import net.spell_engine.api.spell.container.*;import net.spell_engine.internals.*;import net.spell_engine.internals.casting.*;import net.spell_engine.internals.container.*;
@Mod(value="spatial_client_probe",dist=Dist.CLIENT) public class FinalClientProbe {
 int ticks,phase,at;volatile boolean pending;List<String> lines=Collections.synchronizedList(new ArrayList<>());AtomicReference<Throwable> error=new AtomicReference<>();UUID allyId,victimId;double startHealth,abs;
 public FinalClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean ok,String label){lines.add((ok?"PASS ":"FAIL ")+label);if(!ok)throw new AssertionError(label);}
 void server(java.util.function.Consumer<ServerPlayer> task){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{task.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void step(){phase++;at=ticks;}
 void equip(ServerPlayer p,String... ids){var item=new ItemStack(Items.IRON_SWORD);item.set(SpellDataComponents.SPELL_CONTAINER,SpellContainers.forWeapon(SpellContainer.ContentType.ANY,Arrays.stream(ids).map(Identifier::parse).toList()));p.getInventory().setSelectedSlot(0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,item);p.getInventory().setItem(1,new ItemStack(BuiltInRegistries.ITEM.getValue(Identifier.parse("runes:healing_stone")),64));p.inventoryMenu.broadcastFullState();((SpellContainerSource.Owner)p).spellContainerCache().clear();SpellContainerSource.update(p);((SpellCaster.Player)p).getCooldownManager().reset(null);}
 void finish(){phase=99;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("spatial-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("spatial-client-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().handle());net.minecraft.client.KeyMapping.releaseAll();if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(ticks-at>1800)throw new AssertionError("Timeout phase"+phase);
  if(phase==0){mc.options.pauseOnLostFocus=false;mc.setScreenAndShow(null);server(p->{p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.teleportTo(0,101,0);p.removeAllEffects();p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(100);p.getAttribute(Attributes.ARMOR).setBaseValue(0);for(var e:p.level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(100)))if(e!=p)e.discard();for(int x=-25;x<=25;x++)for(int z=-25;z<=25;z++)p.level().setBlock(new net.minecraft.core.BlockPos(x,100,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);equip(p,"paladins:levitate","skill_tree_rpgs:priest_tier_2_spell_2_root","skill_tree_rpgs:priest_tier_2_spell_2_modifier_2");});step();return;}
  if(ticks-at<25)return;
  if(phase==1){check(!PaladinRevamp.spell(mc.player,"paladins:levitate").value().active.cast.haste_affected,"Client receives fixed Ascension timing");server(p->{var h=PaladinRevamp.spell(p,"paladins:levitate");check(PriestRules.node(p,"tier_2_spell_2_modifier_2"),"Real equipped Serenity node recognized");for(int i=0;i<4;i++)PriestRules.ascension(p.level(),h,p,List.of(),new SpellExecution.ImpactContext(1,1,null,new net.spell_power.api.SpellPower.Result(net.spell_power.api.SpellSchools.HEALING,40,0,1),net.spell_engine.internals.target.SpellTarget.FocusMode.DIRECT,i),null);});step();return;}
  if(phase==2){check(mc.player.hasEffect(FinalRules.effect("ascension_guard")),"Ascension defensive effect synchronized");check(mc.player.getEffect(FinalRules.effect("ascension_power")).getAmplifier()==3,"Client sees four offensive stacks");check(mc.player.getAbsorptionAmount()==20,"Client sees actual Serenity20HP amount="+mc.player.getAbsorptionAmount()+" effects="+mc.player.getActiveEffects());server(p->{p.removeAllEffects();p.setAbsorptionAmount(0);p.teleportTo(0,101,0);var category=net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();category.unlock(p);category.setExtraPoints(p,1000);category.getSkill("tdimeso8ajcwiygp").orElseThrow().unlock(p);equip(p,"paladins:immolation");PaladinUltimates.startChannel(p,p.level().getGameTime());var enemy=EntityTypes.CREEPER.create(p.level(),EntitySpawnReason.COMMAND);enemy.setPos(0,101,1);enemy.setNoAi(true);enemy.setNoGravity(true);p.level().addFreshEntity(enemy);victimId=enemy.getUUID();});step();return;}
  if(phase==3){check(mc.player.hasEffect(FinalRules.effect("purgatory_opening")),"Opening armor status synchronized");server(p->{var enemy=(LivingEntity)p.level().getEntity(victimId);var before=enemy.position();enemy.move(MoverType.SELF,new Vec3(0,20,0));check(enemy.getY()<106,"Actual enemy movement blocked by dome roof");enemy.setPos(before);enemy.move(MoverType.SELF,new Vec3(0,-20,0));check(enemy.getY()>96,"Actual enemy movement blocked by dome underside");enemy.setPos(before);check(PurgatoryBoundary.clip(p,new Vec3(30,0,0)).length()>29,"Caster remains exempt from own dome");var eventTeleport=new net.neoforged.neoforge.event.entity.EntityTeleportEvent.EnderEntity(enemy,30,101,0);NeoForge.EVENT_BUS.post(eventTeleport);check(eventTeleport.isCanceled(),"Hostile teleport event denied across dome");var prevented=PaladinRevamp.addControl(p,new MobEffectInstance(FinalRules.effect("spell_engine:stun"),20),enemy);check(prevented,"Early channel still accepts stun");PaladinUltimates.advance(p,p.level().getGameTime());check(PaladinUltimates.channelOf(p)==null,"Early stun releases containment");p.removeAllEffects();PaladinUltimates.startChannel(p,p.level().getGameTime()-160);check(!PaladinRevamp.addControl(p,new MobEffectInstance(FinalRules.effect("spell_engine:stun"),20),enemy),"Late-stage channel retains stun immunity");PaladinUltimates.end(p,PaladinUltimates.End.RELEASE);check(!p.hasEffect(FinalRules.effect("purgatory_opening")),"Early channel release clears opening armor");});step();return;}
  if(phase==4){check(PurgatoryBoundary.active(mc.level).isEmpty(),"Client dome removed on early release");server(p->{equip(p,"skill_tree_rpgs:paladin_tier_3_passive_2");p.removeAllEffects();p.getAttribute(Attributes.MAX_ABSORPTION).setBaseValue(20);p.setAbsorptionAmount(0);p.setHealth(1);var attacker=(LivingEntity)p.level().getEntity(victimId);p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.TOTEM_OF_UNDYING));p.invulnerableTime=0;p.hurtServer(p.level(),p.damageSources().mobAttack(attacker),1000);check(!FinalPurelight.active(p)&&p.isAlive(),"Totem has priority over Purelight");p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);p.removeAllEffects();p.setHealth(1);p.invulnerableTime=0;p.hurtServer(p.level(),p.damageSources().mobAttack(attacker),1000);check(FinalPurelight.active(p)&&p.isAlive()&&!FinalPurelight.downed(p),"Native client-player lethal hit rescued before knockdown");p.setAbsorptionAmount(12);startHealth=p.getHealth();abs=p.getAbsorptionAmount();});step();return;}
  if(phase==5){check(mc.player.hasEffect(FinalRules.effect("purelight_cost")),"Purelight state icon synchronized");server(p->{check(p.getHealth()<startHealth&&p.getAbsorptionAmount()==abs,"Real tick drain reduces health and bypasses absorption");p.removeEffect(FinalRules.effect("purelight_cost"));equip(p);check(FinalPurelight.active(p),"Respec retains irreversible active drain");});step();return;}
  if(phase==6){check(mc.player.hasEffect(FinalRules.effect("purelight_cost")),"Dispelled cost indicator restored while drain remains");server(p->{FinalPurelight.stop(p);equip(p,"skill_tree_rpgs:archer_tier_2_passive_2");SpellTriggers.onRoll(p);});step();return;}
  if(phase==7){check(mc.player.hasEffect(FinalRules.effect("onslaught_ready")),"Onslaught readiness synchronized");server(p->{var enemy=(LivingEntity)p.level().getEntity(victimId);enemy.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);enemy.setHealth(1000);enemy.invulnerableTime=0;enemy.hurtServer(p.level(),p.damageSources().playerAttack(p),10);});step();return;}
  if(phase==8){check(!mc.player.hasEffect(FinalRules.effect("onslaught_ready"))&&mc.player.hasEffect(FinalRules.effect("onslaught_power")),"One direct hit converts client readiness to active buff");server(p->{p.removeAllEffects();equip(p,"skill_tree_rpgs:paladin_tier_3_passive_2");p.setHealth(1);FinalPurelight.rescue(false,p,p.damageSources().mobAttack((LivingEntity)p.level().getEntity(victimId)));if(net.neoforged.fml.ModList.get().isLoaded("playerrevive")){team.creative.playerrevive.server.PlayerReviveServer.getBleeding(p).knockOut(p,p.level().damageSources().generic());check(team.creative.playerrevive.server.PlayerReviveServer.isBleeding(p),"Actual PlayerRevive API enters knocked-down state");}});step();return;}
  if(phase==9){server(p->{if(net.neoforged.fml.ModList.get().isLoaded("playerrevive")){check(!FinalPurelight.active(p),"Actual PlayerRevive downing stops drain");team.creative.playerrevive.server.PlayerReviveServer.getBleeding(p).revive(p);}});step();return;}
  if(phase==10){server(p->{if(net.neoforged.fml.ModList.get().isLoaded("better_revive")){java.util.Map<java.util.UUID,Object> states;try{var field=de.mrstilu2k6.better_revive.util.DownedPlayerManager.class.getDeclaredField("downed");field.setAccessible(true);states=(java.util.Map<java.util.UUID,Object>)field.get(null);}catch(Exception ex){throw new RuntimeException(ex);}p.getPersistentData().putBoolean("final_purelight_active",true);states.put(p.getUUID(),new de.mrstilu2k6.better_revive.util.DownedPlayerManager.DownedState(System.currentTimeMillis(),Long.MAX_VALUE,p.position(),p.level().dimension(),GameType.SURVIVAL));NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));check(!FinalPurelight.active(p),"Better Revive actual downed API stops cost");states.remove(p.getUUID());}});step();return;}
  if(phase==11)finish();
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
